export interface ConnectorConfig {
  githubWebhookSecret: string;
  linearApiKey: string;
  linearTriageTeamId: string;
  fetch?: typeof fetch;
}

export interface GitHubIssuePayload {
  action: string;
  issue: {
    title: string;
    body: string | null;
    html_url: string;
    labels: Array<{ name: string; color: string; description: string | null; default: boolean }>;
  };
  repository: {
    full_name: string;
  };
  sender: {
    login: string;
  };
}

export interface HandleResult {
  linearIssueId: string;
  linearIssueTitle: string;
}

export async function handle(payload: GitHubIssuePayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.action) throw new Error('Missing required field: action');
  if (!payload.issue) throw new Error('Missing required field: issue');
  if (!payload.issue.title) throw new Error('Missing required field: issue.title');
  if (!payload.issue.html_url) throw new Error('Missing required field: issue.html_url');
  if (!payload.repository?.full_name) throw new Error('Missing required field: repository.full_name');
  if (!payload.sender?.login) throw new Error('Missing required field: sender.login');

  if (payload.action !== 'labeled') {
    throw new Error(`Unsupported action: ${payload.action}. Only 'labeled' is processed.`);
  }

  const bugLabel = payload.issue.labels?.find((label) => label.name === 'bug');
  if (!bugLabel) {
    throw new Error("Label 'bug' not found in issue labels.");
  }

  const title = payload.issue.title;
  const description = payload.issue.body ?? '';
  const githubUrl = payload.issue.html_url;
  const repoName = payload.repository.full_name;
  const sender = payload.sender.login;
  const issueNumber = githubUrl.split('/').pop() ?? '';

  const fullDescription = `${description}\n\n---\n*Source: [${repoName}#${issueNumber} by @${sender}](${githubUrl})*`;

  const mutation = `
    mutation IssueCreate($input: IssueCreateInput!) {
      issueCreate(input: $input) {
        success
        issue {
          id
          title
        }
      }
    }
  `;

  const variables = {
    input: {
      title,
      description: fullDescription,
      teamId: config.linearTriageTeamId,
    },
  };

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.linearApiKey}`,
    },
    body: JSON.stringify({ query: mutation, variables }),
  });

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`);
  }

  const result = (await response.json()) as {
    data?: {
      issueCreate?: {
        success: boolean;
        issue?: {
          id: string;
          title: string;
        };
      };
    };
    errors?: Array<{ message: string }>;
  };

  if (result.errors?.length) {
    throw new Error(`Linear GraphQL errors: ${result.errors.map((e) => e.message).join(', ')}`);
  }

  if (!result.data?.issueCreate?.success || !result.data.issueCreate.issue) {
    throw new Error('Linear issue creation failed: unexpected response format');
  }

  return {
    linearIssueId: result.data.issueCreate.issue.id,
    linearIssueTitle: result.data.issueCreate.issue.title,
  };
}

export async function verifyGitHubSignature(rawBody: string, signatureHeader: string, secret: string): Promise<boolean> {
  const prefix = 'sha256=';
  if (!signatureHeader.startsWith(prefix)) return false;
  const providedSig = signatureHeader.slice(prefix.length);
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const messageData = encoder.encode(rawBody);
  const crypto = globalThis.crypto;
  if (!crypto?.subtle) {
    throw new Error('Web Crypto API (crypto.subtle) is not available in this runtime');
  }
  const key = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const signature = await crypto.subtle.sign('HMAC', key, messageData);
  const expectedSig = Array.from(new Uint8Array(signature))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
  return timingSafeEqual(providedSig, expectedSig);
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

